type Tok = string | number;

function tokens(path: string): Tok[] | undefined {
  if (!path.startsWith("$")) return undefined;
  const out: Tok[] = [];
  for (const m of path.slice(1).matchAll(/\.([^.[\]]+)|\[(\d+|\*)\]/g)) out.push(m[2] !== undefined ? (m[2] === "*" ? "*" : Number(m[2])) : (m[1] as string));
  return out;
}
